// Generated by Suite Builder from a crawl of the site. Runs the suite in Chrome when it is installed, else in Electron
// (built into Cypress), and says which.
// EDIT RULES: do not edit this file; regenerating replaces all of it. A --browser given wins; every option passes
// through: npm test -- --browser firefox.
// Creator: https://github.com/ghost-in-the-kernel
import { spawnSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import cypress from 'cypress';

/**
 * --family <name>: every test of that family, in any spec. The family must be declared in
 * cypress/families.txt (a misspelt one would run nothing and pass); only the specs that name it are
 * opened, and inside them the tests outside it are skipped (support/core/Family.ts).
 */
function familyArguments(args) {
  const at = args.indexOf('--family');
  // The unstable spec named alone (the library's button) is a request for its family.
  const spec = args[args.indexOf('--spec') + 1] ?? '';
  if (at < 0 && args.includes('--spec') && spec.split(',').every((s) => s.endsWith('unstable.cy.ts')))
    return [...args, '--expose', 'family=unstable'];
  if (at < 0) return args;
  const name = args[at + 1];
  const declared = readFileSync('cypress/families.txt', 'utf8')
    .split(/\r?\n/)
    .filter((l) => l.trim() && !l.startsWith('#'))
    .map((l) => l.trim().split(/\s+/)[0]);
  if (!name || !declared.includes(name)) {
    console.log(
      `${name ? `No family "${name}"` : 'Which family?'}: the families are ${declared.join(', ')} `
              + `(cypress/families.txt; a family of your own goes in its YOURS block).`,
    );
    process.exit(1);
  }
  const specs = [];
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) walk(path);
      else if (
        entry.name.endsWith('.cy.ts') &&
        new RegExp(`tags:\\s*\\[[^\\]]*['"]${name}['"]`).test(readFileSync(path, 'utf8'))
      )
        specs.push(path.split('\\').join('/'));
      else if (name === 'stories' && /^\s*story\(/m.test(readFileSync(path, 'utf8')))
        specs.push(path.split('\\').join('/'));
    }
  };
  if (existsSync('cypress/e2e')) walk('cypress/e2e');
  if (!specs.length) {
    console.log(
      `No test is in the family "${name}" yet: mark one with { tags: ['${name}'] } in its it() or describe().`,
    );
    process.exit(0);
  }
  console.log(`The family "${name}": ${specs.length} spec${specs.length === 1 ? '' : 's'} hold its tests.`);
  return [
    ...args.slice(0, at),
    ...args.slice(at + 2),
    '--spec',
    [...new Set(specs)].join(','),
    '--expose',
    `family=${name}`,
  ];
}

// The suite's rules first: their report, and a warning for each advisory one. A broken hard or story
// rule fails the run at the end; it never stops the tests from running.
const rules = spawnSync(process.execPath, ['suite-rules/check.mjs'], { stdio: 'inherit' });

const options = await cypress.cli.parseRunArguments(['cypress', 'run', ...familyArguments(process.argv.slice(2))]);
const chosen = options.browser !== undefined;
let result = await cypress.run(chosen ? options : { ...options, browser: 'chrome' });
// No Chrome here: Cypress refuses before any test runs, and Electron always is.
if (
  !chosen &&
  result.status === 'failed' &&
  /browser/i.test(result.message ?? '') &&
  /chrome/i.test(result.message ?? '')
) {
  console.log('Chrome is not installed on this computer: running in Electron, the browser built into Cypress.');
  result = await cypress.run(options);
}
if (result.status === 'failed') console.error(result.message);
if (rules.status !== 0)
  console.log("The suite's rules are broken (above, and cypress/rules-report.md): the run fails for it.");
// A run that stopped early fails: the tests it skipped count as pending, and Cypress would call it passed
// ("All specs passed!" with nothing run).
const stopped = existsSync('cypress/stopped-early.txt') ? readFileSync('cypress/stopped-early.txt', 'utf8').trim() : '';
if (stopped) console.log(
        `The run stopped early (${stopped}): the tests after it did not run, and the run fails for it.`);
process.exit(result.status === 'failed' || result.totalFailed > 0 || rules.status !== 0 || stopped ? 1 : 0);
